</main></div><script>const toggle=document.querySelector('[data-theme-toggle]'),saved=localStorage.getItem('lissi-theme');if(saved)document.documentElement.dataset.theme=saved;toggle?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('lissi-theme',next)});const menu=document.querySelector('[data-menu-toggle]'),sidebar=document.querySelector('[data-sidebar]'),backdrop=document.querySelector('[data-menu-backdrop]');const closeMenu=()=>{sidebar?.classList.remove('is-open');backdrop?.classList.remove('is-visible')};menu?.addEventListener('click',()=>{sidebar?.classList.toggle('is-open');backdrop?.classList.toggle('is-visible')});backdrop?.addEventListener('click',closeMenu);</script></body></html>
